"""Snap span edges to a step and label each span."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """A step is positive and divides an hour evenly."""
    if step <= 0 or 60 % step != 0:
        raise ValueError(f"step {step} must divide 60")

def round_minutes(minutes: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    return (minutes + step // 2) // step * step

def round_span(span: Span, step: int) -> Span:
    return Span(
        round_minutes(span.start, step),
        round_minutes(span.end, step)
    )

def label_span(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m) for one span."""
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"

def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Snap and label each span, in the order given."""
    check_step(step)
    return [
        label_span(round_span(span, step))
        for span in spans
    ]

