import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_quarter_hour(self):
        spans = [Span(542, 1036)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_half_rounds_up(self):
        spans = [Span(545, 605)]
        self.assertEqual(
            round_spans(spans, 10), ["09:10-10:10 (1h 0m)"]
        )

    def test_step_of_one_keeps_times(self):
        spans = [Span(541, 1036)]
        self.assertEqual(
            round_spans(spans, 1), ["09:01-17:16 (8h 15m)"]
        )

    def test_end_of_day_is_allowed(self):
        spans = [Span(1380, 1440)]
        self.assertEqual(
            round_spans(spans, 30), ["23:00-24:00 (1h 0m)"]
        )

    def test_labels_keep_the_given_order(self):
        spans = [Span(600, 720), Span(540, 600)]
        self.assertEqual(
            round_spans(spans, 60),
            ["10:00-12:00 (2h 0m)", "09:00-10:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_rejects_bad_steps(self):
        for step in (0, -15, 7, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(540, 600)], step)

    def test_span_that_collapses_is_rejected(self):
        with self.assertRaises(ValueError):
            round_spans([Span(541, 547)], 15)
